const crypto = require('crypto');
const salt = crypto.randomBytes(16).toString('hex');
const hash = crypto.pbkdf2Sync($json.password, salt, 1000, 64, 'sha512').toString('hex');
return [{ password_hash: hash, salt }];

const crypto = require('crypto');
const hash = crypto.pbkdf2Sync($json.password, $json.salt, 1000, 64, 'sha512').toString('hex');
if (hash === $json.password_hash) {
  return [{ verified: true }];
} else {
  return [{ verified: false }];
}
